import networkx as nx
import itertools

def solve():
    # Number of vertices
    n = 14
    # Fixed edges
    fixed_edges = [(4,5), (0,10), (2,7), (6,8), (2,8), (1,6), (0,9), (5,8)]

    # We need to add edges until all degrees are between 3 and 6.
    # Let's try to build a graph with 28 edges (degree 4 for all).

    import random

    while True:
        G = nx.Graph()
        G.add_nodes_from(range(n))
        G.add_edges_from(fixed_edges)

        # Current degrees
        degrees = [G.degree(i) for i in range(n)]

        # Try to add edges to reach degree 4
        possible_edges = []
        for i in range(n):
            for j in range(i + 1, n):
                if not G.has_edge(i, j):
                    possible_edges.append((i, j))

        random.shuffle(possible_edges)

        for u, v in possible_edges:
            if G.degree(u) < 4 and G.degree(v) < 4:
                G.add_edge(u, v)

        # Check if all degrees are between 3 and 6
        all_ok = True
        for i in range(n):
            if not (3 <= G.degree(i) <= 6):
                all_ok = False
                break

        if all_ok:
            return list(G.edges())

result = solve()
